const raw = ($json.query?.slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!raw) throw new Error('Query parameter "slug" is required.');
return [{ json: { slug: raw } }];

const query = $json.query ?? {};
const rawSlug = (query.slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
const rawFile = (query.file ?? '').toString().trim();
if (!rawSlug) throw new Error('Query parameter "slug" is required.');
if (!rawFile) throw new Error('Query parameter "file" is required.');

// Anchored allowlist: no traversal (".." and leading "/" can never match).
const ALLOWED = /^(script\.json|project\.json|shots\/shot_[a-z0-9_]+\.png|shots\/contact_sheet\.jpg|refs\/anchors\/char_[a-z0-9_]+\.(jpg|png)|audio\/shot_[a-z0-9_]+\.mp3|videos\/shot_[a-z0-9_]+\.mp4|audio\/lines\/line_[a-z0-9_]+\.mp3|film\.mp4)$/;
if (!ALLOWED.test(rawFile)) throw new Error('Invalid file path: ' + rawFile);

const MIME = {
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.mp3': 'audio/mpeg',
  '.mp4': 'video/mp4',
};
const ext = '.' + rawFile.split('.').pop().toLowerCase();
return [{ json: {
  slug: rawSlug,
  filePath: '/home/node/files/films/' + rawSlug + '/' + rawFile,
  contentType: MIME[ext] || 'application/octet-stream',
}}];
